  eqOpen(kind){ const list = [...(state.data.equipment_types || [])].sort((a, b) => (a.sort || 0) - (b.sort || 0));
    eqDraft = { kind, et: (list[0] || {}).id || null, qty: 1, src: 'stock', note: '' }; eqModal(); },
  eqEt(id){ if (eqDraft){ eqKeepNote(); eqDraft.et = id; eqModal(); } },
