function mediaQueueCardHtml(){
  const st = mqState();
  const nV = mediaQ.filter(x => x.kind === 'video').length, nP = mediaQ.length - nV;
  return `<div class="card"${st.key === 'ok' ? '' : ' style="border-color:var(--orange)"'}>
    <div style="font-weight:900;margin-bottom:6px">${mqStateHtml()}</div>
    ${st.key === 'ok'
      ? `<div class="tiny" style="margin-bottom:8px">${t('mq_empty')}</div>`
      : `<div class="tiny" style="margin-bottom:8px">${nP} ${t('mq_photo')} · ${nV} ${t('mq_video')} · ${t('mq_pending')}</div>`}
    <button class="btn ${st.key === 'ok' ? 'btn-ghost' : 'btn-blue'}" onclick="App.mediaQueueModal()">${st.key === 'ok' ? t('mq_open') : t('mq_check')}</button>
    <label class="opt ${mqQuiet() ? 'on' : ''}" style="margin-top:8px">
      <input type="checkbox" ${mqQuiet() ? 'checked' : ''} onchange="App.mqQuiet(this.checked)"> ${t('mq_quiet')}</label>
    <div class="tiny">${t('mq_quiet_h')}</div>
  </div>`;
}
function mediaQueueModal(){
  const nV = mediaQ.filter(x => x.kind === 'video').length, nP = mediaQ.length - nV;
  const groups = {};
  mediaQ.forEach(it => { (groups[it.job_id] = groups[it.job_id] || []).push(it); });
  const ids = Object.keys(groups);
  const cards = ids.map(id => {
    const arr = groups[id];
    const j = state.data.jobs.find(x => x.id === id);
    const cx = j ? (cxById(j.complex_id) || {}) : {};
    const title = j
      ? `${esc(cx.abbr || cx.name || '—')} · Unit <b>${esc(j.unit_number || '—')}</b> · ${fmtDMY(j.date)}`
      : `${t('mq_doc')} …${esc(String(id).slice(0, 8))}`;
    const v = arr.filter(x => x.kind === 'video').length, ph = arr.length - v;
    const th = arr.slice(0, 4).map(x => {
      try{ return x.thumb ? `<img class="mq-th" src="${URL.createObjectURL(x.thumb)}" alt="">` : ''; }
      catch(e){ return ''; }
    }).join('');
    return `<div class="card" style="padding:8px 10px;margin:6px 0">
      <div style="display:flex;gap:8px;align-items:center">
        <div class="grow">${title}
          <div class="tiny">${ic('upload')} ${ph} ${t('mq_photo')} · ${v} ${t('mq_video')}</div></div>
        ${j ? `<button class="btn btn-ghost sm" onclick="App.closeModal();App.openJob('${id}')">${ic('send')}</button>` : ''}
      </div>
      ${th ? `<div class="mq-ths">${th}</div>` : ''}
    </div>`;
  }).join('');
  openModal(`
    ${modalHead(mqState().text, mqState().key === 'ok' ? 'check' : 'sync')}
    <div class="card" style="padding:8px 10px;margin-bottom:8px">
      <b>${mediaQ.length ? `${ids.length} ${t('mq_docs')} · ${nP} ${t('mq_photo')} · ${nV} ${t('mq_video')}`
                         : t('mq_all_ok')}</b>
      <div class="tiny" id="mq-conn" style="margin-top:4px">${ic('wifi',
        navigator.onLine ? '' : 'color:var(--red)')} ${navigator.onLine ? t('mq_net_on') : t('mq_net_off')}</div>
    </div>
    ${mediaQ.length ? cards : `<div class="card" style="padding:10px">${ic('check', 'color:var(--green)')} ${t('mq_empty')}</div>`}
    <div class="btn-rowpp" style="margin-top:10px">
      <button class="btn btn-ghost" id="mq-btn-ping" onclick="App.mqPing()">${t('mq_ping')}</button>
      <button class="btn btn-green" id="mq-btn-send" ${mediaQ.length ? '' : 'disabled'} onclick="App.mqRetry()">${ic('upload')} ${t('mq_retry')}</button>
    </div>
    ${mqStuck().length ? `<button class="btn btn-ghost sm" style="margin-top:6px"
      onclick="App.mqClean()">${ic('trash')} ${t('mq_clean')} · ${mqStuck().length}</button>` : ''}
    <div class="tiny" style="margin:10px 0 4px;color:var(--dim)">${t('mq_log')}</div>
    <div class="mq-log" id="mq-log"></div>`);
  mqLogPaint();
  mqSetBusy(_mqBusy);
}
async function mqPing(){
  if (_mqBusy) return;                   // v1.07.63: идёт отправка — кнопка заблокирована
  mqSetBusy('ping');
  const el = $('#mq-conn');
  const lid = mqLog('🧪 ' + t('mq_ping') + ' …', 'dim');
  try{
    const net = navigator.onLine;
    mqLog((net ? '🌐 ' : '🔴 ') + (net ? t('mq_net_on') : t('mq_net_off')), net ? 'ok' : 'err', lid);
    let sb = '';
    if (HAS_SB && state.sb){
      const t0 = Date.now();
      try{
        const { error } = await state.sb.from('profiles').select('id', { head: true, count: 'exact' }).limit(1);
        if (error) throw error;
        sb = ` · Supabase ✓ ${Date.now() - t0} ms`;
        mqLog(`✓ Supabase — ${Date.now() - t0} ms`, 'ok');
      }catch(e){
        sb = ' · ⛔ Supabase: ' + t('mq_sb_fail');
        mqLog('⛔ Supabase — ' + t('mq_sb_fail'), 'err');
      }
      try{                               // задеплоены ли edge-функции
        const token = await mediaJwt();
        const r = await fetch(mediaFN() + '/media-health',
          { headers: { Authorization: 'Bearer ' + (token || '') } });
        if (r.status === 404) mqLog('⛔ ' + t('mq_l_fn') + ' — ' + t('mq_l_fn_no'), 'err');
        else mqLog('✓ ' + t('mq_l_fn'), 'ok');
      }catch(e){ mqLog('⛔ ' + t('mq_l_fn') + ' — ' + t('mq_l_fn_no'), 'err'); }
    }
    if (_mediaRelay) mqLog('⚠ ' + t('mq_l_relay_on'), 'warn');
    if (el) el.innerHTML = ic('wifi', net ? '' : 'color:var(--red)') + ' '
      + esc((net ? t('mq_net_on') : t('mq_net_off')) + sb);
  } finally { mqSetBusy(''); }
}
async function mqRetry(){
  if (_mqBusy) return;                   // v1.07.63: идёт проверка связи — не мешаем
  mqSetBusy('send');
  for (const it of mediaQ){ if (it.attempts){ it.attempts = 0; await mQPut(it); } }
  const n0 = mediaQ.length;
  mqLog(`⬆ ${t('mq_l_start')} · ${n0} ${t('mq_l_files')}`, 'dim');
  let r = { photo: 0, video: 0, fail: 0, stopped: false };
  try{ r = (await mediaFlush(true)) || r; }
  catch(e){ mqLog('⛔ ' + esc(String(e && e.message || e)), 'err'); }
  const sent = r.photo + r.video;
  if (sent) mqLog(`✅ ${t('mq_l_sent')}: ${r.photo} ${t('mq_photo')} · ${r.video} ${t('mq_video')}`, 'ok');
  else if (!r.fail) mqLog('… ' + t('mq_l_none'), 'warn');
  if (mediaQ.length) mqLog(`⚠ ${t('mq_l_left')}: ${mediaQ.length}` + (r.stopped ? ' · ' + t('mq_l_stop') : ''), 'warn');
  else if (sent) mqLog('✅ ' + t('mq_empty'), 'ok');
  mqSetBusy('');
  mediaQueueModal();                     // пересобрать с актуальной очередью (журнал сохраняется)
  toast(mediaQ.length ? '⚠ ⬆' + mediaQ.length + ' ' + t('media_wait') : '✓ ' + t('mq_empty'));
}
/* ---------- моточасы осушителя ---------- */
async function plHours(pid, field, val){
  const p = state.data.placements.find(x => x.id === pid);
  if (!p || !state.user || !canTouchPk(p)) return;
  const v = String(val).trim() === '' ? null : parseFloat(String(val).replace(',', '.'));
  if (v !== null && !(v >= 0)){ toast('⚠ 0+', 'err'); return; }
  await dbUpsert('placements', { ...p, [field]: v });
}
/* =====================================================================
   v1.07.64: ЛИМИТЫ МЕДИА, МЕСТО НА ДИСКЕ, КАРТОЧКА КЛЮЧЕЙ.
   Ключи хранятся на сервере: в карточку подтягивается то, что не секрет
   (Client ID, ID папки, аккаунт), секреты показываются звёздочками —
   реальное значение приходит отдельным запросом и только по клику «глаза».
   ===================================================================== */
