/* Свободное место на Диске: снимается при «Тесте соединения» и при заливке
   файлов (сервером, не чаще раза в 6 часов) — в org_settings, поэтому видно
   и менеджеру. Порог — 15 %. */
const GD_LOW_PCT = 15;
function gdFreePct(){
  const o = (state.data && state.data.org_settings) || {};
  const p = Number(o.gd_free_pct);
  return (o.gd_checked_at && isFinite(p)) ? p : null;
}
function gdSpaceBannerHtml(){
  if (!isManager()) return '';                       // только админ и менеджер
  const p = gdFreePct();
  if (p === null || p >= GD_LOW_PCT) return '';
  const o = state.data.org_settings || {};
  return `<div class="banner b-red" role="status">${ic('warn')}
    <div class="grow">${t('gd_space_warn')
      .replace('{P}', Math.max(0, Math.round(p)))
      .replace('{U}', (+o.gd_used_gb || 0).toFixed(1))
      .replace('{L}', (+o.gd_limit_gb || 0).toFixed(0))}</div></div>`;
}
/* ---------- админка: ключи, подключение, тест ---------- */
let gdCfg = { loaded: false, client_id: '', folder_id: '', account: '',
              has_secret: false, has_refresh: false, secret: '', refresh: '' };
let gdEdit = false;
/* v1.07.78: где на Диске лежат файлы — заполняется «Тестом соединения»
   (media-health возвращает имена и адреса папок) и рисуется карточкой. */
let gdFolders = null;
/* =====================================================================
   v1.08.36 · ИМЕНА ТРЁХ КОРНЕВЫХ ПАПОК — НАПРОТИВ ПОЛЕЙ ВВОДА.
   Источник истины — сам Диск: media-health?names=1 резолвит имена по ID
   (лёгкая ветка, без квоты и write-теста). Старая сборка функции ветки
   не знает и вернёт полную проверку — имена берём из её r.paths.
   Кэш в localStorage: подписи видны сразу, обновляются тихо в фоне.
   ===================================================================== */
let gdNames = null;
try { gdNames = JSON.parse(localStorage.getItem('tl_gd_names') || 'null'); } catch(e){}
function gdNamesFrom(j){
  if (j && j.names) return j.names;
  if (j && j.paths){
    const g = k => { const p = j.paths[k];
      return p && p.root ? { id: p.root.id || '', name: p.root.name || '', own: !!p.root.own } : null; };
    return { root: j.folder ? { id: j.folder.id, name: j.folder.name || '' } : null,
             photo: g('photo'), invoice: g('invoice'), file: g('file') };
  }
  return null;
}
function gdNmBad(kind){
  const n = gdNames && gdNames[kind];
  return n && n.own && !n.name ? ' bad' : '';
}
function gdNmHtml(kind){
  const n = (gdNames && gdNames[kind]) ||
    (gdFolders && gdFolders[kind] && gdFolders[kind].root
      ? { name: gdFolders[kind].root.name, own: true } : null);
  if (!n) return HAS_SB && isAdmin() && gdHasKeys() ? `<span class="tiny">${t('gd_nm_wait')}</span>` : '';
  if (n.own && !n.name) return `⚠ ${t('gd_nm_bad')}`;
  return n.name ? `${ic('folder')} ${esc(n.name)}` : '';
}
function gdNamesApply(n){
  if (!n) return;
  gdNames = n;
  try { localStorage.setItem('tl_gd_names', JSON.stringify(n)); } catch(e){}
  [['photo', 'gd-nm-photo'], ['invoice', 'gd-nm-inv'], ['file', 'gd-nm-files']]
    .forEach(([k, id]) => { const el = document.getElementById(id);
      if (el) { el.innerHTML = gdNmHtml(k); el.title = (n[k] && n[k].name) || '';
        el.classList.toggle('bad', !!(n[k] && n[k].own && !n[k].name)); } });
}
let gdNamesAt = 0, gdFnFresh = null;   // null — версия функции ещё не выяснена
async function gdNamesRefresh(extra){
  if (!HAS_SB || !isAdmin() || !gdHasKeys()) return;
  const now = Date.now();
  if (!extra && now - gdNamesAt < 15000) return;      // фон — не чаще раза в 15с
  gdNamesAt = now;
  try{
    /* Старая сборка media-health ветки ?names=1 не знает и провалилась бы в
       ПОЛНУЮ проверку (write-тест на Диске) при каждом открытии карточки.
       Поэтому сперва дешёвый ping: функция моложе 1.08.36 — фоновых запросов
       не делаем, подписи придут из кэша или из кнопки «Тест соединения». */
    if (gdFnFresh === null){
      try{
        const pj = await (await fetch(mediaFN() + '/media-health?ping=1')).json();
        const v = String((pj && pj.ver) || '').split('.').map(Number);
        gdFnFresh = v.length === 3 && v.every(isFinite)
          && (v[0] * 1e6 + v[1] * 1e3 + v[2]) >= 1e6 + 8e3 + 36;
      }catch(e){ gdFnFresh = false; }
    }
    if (!gdFnFresh) return;
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-health?names=1' + (extra || ''),
      { headers: { Authorization: 'Bearer ' + token } });
    if (!r.ok) return;
    const j = await r.json().catch(() => null);
    gdNamesApply(gdNamesFrom(j));
  }catch(e){ /* тихо: подпись просто не обновится в этот раз */ }
}
function gdTrimOn(){ try{ return localStorage.getItem('techlog_gd_trim') !== '0'; }catch(e){ return true; } }
function gdTrimToggle(on){
  try{ localStorage.setItem('techlog_gd_trim', on ? '1' : '0'); }catch(e){}
  render();
}
/* Живая обрезка вставленного адреса: из
   https://drive.google.com/drive/folders/1AbC…XyZ?usp=sharing остаётся 1AbC…XyZ */
function gdFolderInput(el){
  if (!el) return;
  const raw = el.value;
  if (gdTrimOn()){
    const id = gdFolderId(raw);
    if (id && id !== raw) el.value = id;
  }
  const chip = $('#gd-folder-chip');
  if (chip){
    const v = (el.value || '').trim();
    const known = gdFolders && gdFolders.root && gdFolders.root.id === v ? gdFolders.root.name : '';
    chip.innerHTML = v
      ? `${ic('folder')} ${esc(known || v)}${known ? '' : ` · <span class="tiny">${t('gd_folder_unknown')}</span>`}`
      : '';
    chip.style.display = v ? 'inline-flex' : 'none';
  }
}
/* Карточка «куда сохраняются файлы»: отдельно фото и видео, отдельно
   документы — с именем папки и ссылкой, как в Google Диске. */
/* v1.07.87: как будет выглядеть путь инвойса при нынешних настройках */
/* v1.08.12: рядом с полем — как эта папка называется на Диске.
   Имя приходит из «Теста соединения» (его знает только сервер). */
function gdDirName(kind){
  const p = (typeof gdFolders !== 'undefined' && gdFolders) ? gdFolders[kind] : null;
  if (!p) return '';
  /* v1.08.25: имя именно корня. Раньше брался первый кусок пути — у своей
     папки админа это было её имя, а у папки внутри архива — имя архива. */
  const nm = (p.root && p.root.name) || String(p.path || '').split('/')[0].trim();
  return nm ? ` <span class="gd-mark">${esc(nm)}</span>` : '';
}
function gdInvPathSample(){
  const o = state.data.org_settings || {};
  const ym = todayISO().slice(0, 7).replace('-', '_');    // v1.08.25: на Диске 2026_09
  const root = String(o.gd_inv_folder || '').trim() ? t('gd_own_folder') : t('gd_arch_inv');
  const me = translit(shortName((state.user && state.user.display_name) || 'Ivan Petrov')).replace(/\.$/, '');
  return o.gd_inv_by_tech ? `${root} / ${me} / ${ym}` : `${root} / ${ym}`;
}
/* v1.08.25: корень и конечная папка — разные вещи, и в карточке они теперь
   разведены. media-health присылает корень (имя, id, лежит ли он в архиве) и
   схему записи токенами; токены расшифровываются здесь, поэтому подписи идут
   на языке интерфейса. У съёмки схема своя — контрагент / комплекс / юнит. */
const GD_SEG_KEY = { cp: 'gd_seg_cp', cx: 'gd_seg_cx', unit: 'gd_seg_unit',
                     tech: 'gd_seg_tech', doc: 'gd_seg_doc' };
function gdSegText(seg, ym){
  if (seg === 'ym') return ym || todayISO().slice(0, 7).replace('-', '_');
  return GD_SEG_KEY[seg] ? '<' + t(GD_SEG_KEY[seg]) + '>' : String(seg);
}
function gdPathParts(kind){
  const p = gdFolders ? gdFolders[kind] : null;
  if (!p) return null;
  if (p.root && (p.root.name || p.root.id)){
    const r = p.root;
    return { id: r.id || p.id || '',
             root: (r.own || !r.in) ? (r.name || '—') : `${r.in} / ${r.name}`,
             segs: (p.scheme || []).map(x => gdSegText(x, p.ym)), legacy: false };
  }
  /* старая версия функции отдавала один путь строкой — разбираем как есть */
  const segs = String(p.path || '').split('/').map(x => x.trim()).filter(Boolean);
  return { id: p.id || '',
           root: segs.slice(0, Math.max(1, segs.length - 1)).join(' / ') || (p.name || '—'),
           segs: segs.length > 1 ? [segs[segs.length - 1]] : [], legacy: true };
}
function gdFoldersHtml(){
  if (!gdFolders || !gdFolders.root) return '';
  let old = false;
  const row = (lbl, kind, note) => {
    const p = gdPathParts(kind);
    if (!p || !p.id) return `<div class="gd-fold">${ic('folder')}
      <div class="gf-b"><div class="gf-n">${esc(lbl)}</div>
        <div class="gf-p">${t('gd_folder_unknown')}</div></div></div>`;
    if (p.legacy) old = true;
    return `<div class="gd-fold">${ic('folder')}
      <div class="gf-b">
        <div class="gf-n wrap">${esc(lbl)}</div>
        <div class="gf-p2"><b>${t('gd_root')}:</b> ${esc(p.root)}</div>
        <div class="gf-p2"><b>${t('gd_into')}:</b> ${p.segs.length
          ? p.segs.map(x => `<span class="gd-seg">${esc(x)}</span>`).join('<i>/</i>')
          : `<span class="dim">${t('gd_into_root')}</span>`}</div>
        ${note ? `<div class="gf-p2 dim">${esc(note)}</div>` : ''}
      </div>
      <a href="https://drive.google.com/drive/folders/${encodeURIComponent(p.id)}" target="_blank" rel="noopener">${t('gd_open_drive')}</a></div>`;
  };
  const rows = row(t('gd_where_photo'), 'photo', t('gd_photo_note'))
             + row(t('gd_where_files'), 'file')
             + row(t('gd_where_inv'), 'invoice');
  return `<div style="margin-top:8px">
    <div class="tiny" style="font-weight:900;margin-bottom:4px">${t('gd_where')}</div>
    ${rows}
    ${old ? `<div class="tiny gd-hint">${ic('warn')} ${t('gd_paths_old')}</div>` : ''}
    <button class="btn btn-blue" style="margin-top:6px" onclick="App.gdCycle()">${ic('sync')} ${t('gd_cyc')}</button>
    <div class="tiny gd-hint">${t('gd_cyc_hint')}</div>
    <div id="gd-cycle" style="margin:4px 0"></div>
    <button class="btn btn-ghost" style="margin-top:6px" onclick="App.gdMove()">${ic('folder')} ${t('gd_move')}</button>
    <div class="tiny dim" style="margin-top:4px">${t('gd_move_hint')}</div>
  </div>`;
}
/* v1.07.81 · разовый переезд старых месяцев в «Photos».
   До этой версии съёмка ложилась прямо в корень архива, поэтому у тех, кто
   работает давно, там уже лежат папки 2026-08, 2026-09 … Кнопка просит
   media-health перенести их внутрь «Photos»; адреса файлов не меняются,
   повторное нажатие ничего не ломает — переносить будет нечего. */
async function gdMove(){
  if (!HAS_SB || !isAdmin()) return;
  const box = $('#gd-health');
  try{
    const token = await mediaJwt();
    toast('⏳ …', 'inf');
    const r = await fetch(mediaFN() + '/media-health?migrate=1',
      { method: 'POST', headers: { Authorization: 'Bearer ' + token } });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || j.error) throw new Error(j.error || ('HTTP ' + r.status));
    const n = j.moved || 0;
    toast('✓ ' + (n ? t('gd_move_done').replace('{N}', n) : t('gd_move_none')));
    dlog('drive: перенесено папок', n, '· файлов', j.merged || 0);
    if (box) box.innerHTML += `<div>${ic('dot', 'color:var(--green)')} ${t('gd_move')} — ${esc(String(n))}</div>`;
    await mediaHealth();                       // пути в карточке — заново
  }catch(e){ toast('⛔ ' + String(e.message || e).slice(0, 90), 'err'); }
}
const gdShow = { sec: false, ref: false };
function gdHasKeys(){ return !!(gdCfg.client_id || gdCfg.has_secret || gdCfg.folder_id); }
function gdEditMode(){ return gdEdit || !gdHasKeys(); }
function gdMask(real, fallback){
  const s = String(real || '');
  if (!s) return fallback || '';
  if (s.length <= 8) return '••••••••';
  return s.slice(0, 4) + '••••••••••••' + s.slice(-4);
}
/* «https://drive.google.com/drive/folders/1AbC…XyZ?usp=sharing» → «1AbC…XyZ» */
function gdFolderId(v){
  const s = String(v || '').trim();
  const m = s.match(/\/folders\/([^/?#]+)/) || s.match(/[?&]id=([^&#]+)/);
  if (m) return m[1];
  return s.replace(/^https?:\/\/[^/]+\//i, '').replace(/[?#].*$/, '').replace(/\/+$/, '');
}
async function gdLoadCfg(force){
  if (!HAS_SB || !isAdmin()) return;
  if (gdCfg.loaded && !force) return;
  /* v1.08.03: если edge-функции ещё не задеплоены, запрос падает, gdCfg.loaded
     остаётся снятым — и КАЖДЫЙ следующий рендер «Настроек» заводил новый
     запрос. При обновлении по таймеру это давало поток неудачных обращений и
     подтормаживание экрана. Держим паузу между попытками. */
  if (!force){
    const now = Date.now();
    if (gdCfg._busy || (gdCfg._try && now - gdCfg._try < 30000)) return;
    gdCfg._try = now;
  }
  gdCfg._busy = true;
  gdCfg.loaded = true;
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-health?cfg=1',
      { headers: { Authorization: 'Bearer ' + token } });
    const j = await r.json().catch(() => ({}));
    if (j && j.cfg){ Object.assign(gdCfg, j.cfg); if (state.screen === 'settings') render(); }
  }catch(e){ dlog('gd cfg', e); }     // функции не задеплоены — форма останется на вводе
  finally { gdCfg._busy = false; }
}
async function gdFetchSecrets(){
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-health?reveal=1',
      { headers: { Authorization: 'Bearer ' + token } });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.secrets) throw new Error(j.error || r.status);
    gdCfg.secret = j.secrets.client_secret || '';
    gdCfg.refresh = j.secrets.refresh_token || '';
    return true;
  }catch(e){ toast('⛔ ' + t('gd_reveal_err') + ': ' + (e.message || e), 'err'); return false; }
}
async function gdReveal(which){
  if (gdShow[which]){ gdShow[which] = false; render(); return; }
  const need = which === 'sec' ? !gdCfg.secret : !gdCfg.refresh;
  if (need && !(await gdFetchSecrets())) return;
  gdShow[which] = true; render();
}
async function gdCopy(which){
  let v = '';
  if (which === 'cid') v = gdCfg.client_id;
  else if (which === 'folder') v = gdCfg.folder_id;
  else if (which === 'redirect') v = location.origin + location.pathname;
  else {
    if ((which === 'sec' && !gdCfg.secret) || (which === 'ref' && !gdCfg.refresh)){
      if (!(await gdFetchSecrets())) return;
    }
    v = which === 'sec' ? gdCfg.secret : gdCfg.refresh;
  }
  if (!v){ toast('⚠ ' + t('gd_none'), 'err'); return; }
  try{ await navigator.clipboard.writeText(v); toast('✓ ' + t('copied')); }
  catch(e){ toast('⛔ ' + (e.message || e), 'err'); }
}
