async function mediaSaveKeys(){
  if (!HAS_SB){ toast(t('media_sb_only'), 'err'); return; }
  if (!gdEditMode()) return;             // v1.07.64: форма в режиме просмотра — сохранять нечего
  const cid = (($('#gd-cid') || {}).value || '').trim(),
        sec = (($('#gd-sec') || {}).value || '').trim(),
        fld = gdFolderId(($('#gd-folder') || {}).value || '');   // ссылка целиком → ID
  const { error } = await state.sb.rpc('admin_set_drive_config',
    { p_client_id: cid, p_client_secret: sec, p_refresh_token: '', p_folder_id: fld });
  if (error){ toast('⛔ ' + rpcFail(error, 'admin_set_drive_config'), 'err'); return; }
  if (cid) gdCfg.client_id = cid;
  if (fld) gdCfg.folder_id = fld;
  if (sec){ gdCfg.has_secret = true; gdCfg.secret = sec; }
  toast('✓ ' + t('gd_saved'));
}
async function mediaConnect(){
  if (!HAS_SB){ toast(t('media_sb_only'), 'err'); return; }
  const cid = ((($('#gd-cid') || {}).value || gdCfg.client_id) || '').trim();
  if (!cid){ toast('⚠ ' + t('gd_need_cid'), 'err'); return; }
  await mediaSaveKeys();                 // в режиме просмотра сохранение пропускается
  const redirect = location.origin + location.pathname;
  const u = 'https://accounts.google.com/o/oauth2/v2/auth'
    + '?client_id=' + encodeURIComponent(cid)
    + '&redirect_uri=' + encodeURIComponent(redirect)
    + '&response_type=code'
    + '&scope=' + encodeURIComponent('https://www.googleapis.com/auth/drive.file')
    + '&access_type=offline&prompt=consent&state=tl_drive';
  location.href = u;
}
async function mediaOauthExchange(code){
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-oauth', { method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
      body: JSON.stringify({ code, redirect_uri: location.origin + location.pathname }) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.ok) throw new Error(j.error || r.status);
    toast('✓ ' + t('gd_connected') + (j.email ? ' · ' + j.email : ''));
    App.go('settings');
  }catch(e){ toast('⛔ Google OAuth: ' + (e.message || e), 'err'); }
}
/* v1.07.72: комплект функций, который должен стоять на сервере, и ожидаемая
   версия. Каждая функция на ?ping=1 отвечает своим именем — так видно и
   перепутанный при ручном деплое код, и забытую при обновлении функцию. */
const MEDIA_FNS = ['media-health', 'media-begin', 'media-put', 'media-commit',
                   'media-view', 'media-delete', 'media-oauth'];
const MEDIA_FN_VER = '1.08.12';
/* v1.07.76: не каждая правка задевает все функции — у каждой свой минимум,
   и передеплоя просит только та, где код действительно поменялся. */
const MEDIA_FN_MIN = { 'media-begin': '1.08.25', 'media-commit': '1.08.13', 'media-health': '1.08.25',
                       'media-delete': '1.07.88' };
const MEDIA_FN_MIN_DEF = '1.07.72';
function mFnVerOk(ver, name){
  const need = (MEDIA_FN_MIN[name] || MEDIA_FN_MIN_DEF).split('.').map(Number);
  const got = String(ver || '0').split('.').map(Number);
  for (let i = 0; i < 3; i++){
    if ((got[i] || 0) > (need[i] || 0)) return true;
    if ((got[i] || 0) < (need[i] || 0)) return false;
  }
  return true;
}
async function gdFnCheck(row){
  const token = await mediaJwt();
  let bad = 0;
  for (const name of MEDIA_FNS){
    try{
      const r = await fetch(`${mediaFN()}/${name}?ping=1`,
        { headers: { Authorization: 'Bearer ' + token } });
      if (r.status === 404){ row(name, false, t('gd_fn_no')); bad++; continue; }
      const j = await r.json().catch(() => ({}));
      if (!j || !j.fn){ row(name, false, t('gd_fn_old') + ' · HTTP ' + r.status); bad++; continue; }
      if (j.fn !== name){ row(name, false, t('gd_fn_wrong').replace('{X}', esc(String(j.fn)))); bad++; continue; }
      const fresh = mFnVerOk(j.ver, name);
      row(name, fresh, fresh ? 'v' + j.ver
        : t('gd_fn_stale').replace('{V}', esc(String(j.ver || '?')))
            .replace('{E}', MEDIA_FN_MIN[name] || MEDIA_FN_MIN_DEF));
      if (!fresh) bad++;
    }catch(e){ row(name, false, String(e.message || e).slice(0, 80)); bad++; }
  }
  return bad;
}
/* v1.07.70: маленькая тестовая картинка — рисуем на месте, чтобы проверять
   загрузку настоящими байтами, а не пустым запросом. */
async function mTestBlob(){
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d');
  g.fillStyle = '#0F171B'; g.fillRect(0, 0, 64, 64);
  g.fillStyle = '#58CC02'; g.fillRect(4, 4, 56, 56);
  g.fillStyle = '#0E2A00'; g.font = 'bold 22px sans-serif'; g.fillText('TL', 15, 32);
  g.font = '8px sans-serif'; g.fillText(new Date().toISOString().slice(11, 19), 8, 50);
  return await new Promise(res => c.toBlob(res, 'image/jpeg', 0.8));
}
/* Проверяем путь настоящего фото целиком. row(name, ok|null, extra) — строка
   отчёта, одна и та же и в «Тесте соединения», и в «Диагностике». */
async function gdProbe(row){
  const token = await mediaJwt();
  const blob = await mTestBlob();
  const ids = [], range = `bytes 0-${blob.size - 1}/${blob.size}`;

  /* 1. хранилище миниатюр. Политика пускает запись только по адресу из
     записи media, поэтому отказ RLS на тестовом пути — это работающая
     защита, а не поломка: важно, что bucket на месте и правило действует. */
  const key = '_selftest/' + uid() + '.jpg';
  try{
    const { error } = await state.sb.storage.from('media-thumbs')
      .upload(key, blob, { contentType: 'image/jpeg', upsert: true });
    if (error){
      if (/row-level security|violates/i.test(String(error.message || error)))
        row(t('gd_p_thumb'), true, t('gd_p_thumb_rls'));
      else throw error;
    } else {
      await state.sb.storage.from('media-thumbs').remove([key]);
      row(t('gd_p_thumb'), true, (blob.size / 1024).toFixed(1) + ' KB');
    }
  }catch(e){ row(t('gd_p_thumb'), false, String(e.message || e).slice(0, 90)); }
  /* v1.07.72: та же проверка сервером — RLS её не закрывает, поэтому видно,
     жив ли сам bucket, а не только политика */
  try{
    const r = await fetch(mediaFN() + '/media-health?storage=1',
      { method: 'POST', headers: { Authorization: 'Bearer ' + token } });
    const j = await r.json().catch(() => ({}));
    row(t('gd_p_thumb_srv'), !!j.ok, j.ok ? '' : String(j.error || ('HTTP ' + r.status)).slice(0, 90));
  }catch(e){ row(t('gd_p_thumb_srv'), false, String(e.message || e).slice(0, 90)); }

  const session = async (kind) => {
    const r = await fetch(mediaFN() + '/media-health?probe=1', { method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
      body: JSON.stringify({ size: blob.size, kind: kind || 'photo' }) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.upload_url) throw new Error(j.error || ('HTTP ' + r.status));
    return j;
  };

  /* 2. сессия докачки + признак, ушёл ли Origin (без него браузер не пустят) */
  let s1 = null;
  try{
    s1 = await session();
    row(t('gd_p_session'), !!s1.origin, s1.origin ? 'Origin ✓' : t('gd_p_origin_no'));
  }catch(e){ row(t('gd_p_session'), false, String(e.message || e).slice(0, 90)); }

  /* 3. байты из браузера напрямую — тот самый шаг, который молча падал */
  let direct = false;
  if (s1){
    try{
      const r = await fetch(s1.upload_url, { method: 'PUT',
        headers: { 'Content-Range': range }, body: blob });
      const j = r.ok ? await r.json().catch(() => ({})) : {};
      direct = !!j.id; if (j.id) ids.push(j.id);
      row(t('gd_p_direct'), direct, direct ? '' : 'HTTP ' + r.status);
    }catch(e){
      row(t('gd_p_direct'), false,
        mIsNetErr(e) ? t('gd_p_cors') : String(e.message || e).slice(0, 90));
    }
  } else row(t('gd_p_direct'), null, t('gd_p_skip'));

  /* 4. байты через сервер-посредник — запасной путь тоже должен работать */
  let relay = false;
  try{
    const s2 = await session();
    const r = await fetch(mediaFN() + '/media-put', { method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'x-tl-url': s2.upload_url, 'x-tl-range': range },
      body: blob });
    const j = await r.json().catch(() => ({}));
    relay = !!j.id; if (j.id) ids.push(j.id);
    row(t('gd_p_relay'), relay, relay ? '' :
      String(j.error || ('HTTP ' + (j.status || r.status))).slice(0, 90));
  }catch(e){ row(t('gd_p_relay'), false, String(e.message || e).slice(0, 90)); }

  /* v1.07.81: у съёмки теперь тоже своя папка — показываем, куда именно
     открылась сессия, и краснеем, если это не «Photos» (значит, на сервере
     осталась старая media-begin/media-health). */
  const wPhoto = (s1 && s1.folder && s1.folder.path) || '';
  if (wPhoto) row(t('gd_p_photo'), /Photos/.test(wPhoto), esc(wPhoto));

  /* v1.07.76: вложение «скрепкой» проверяем отдельно — у него своя папка */
  try{
    const sf = await session('file');
    const r = await fetch(mediaFN() + '/media-put', { method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'x-tl-url': sf.upload_url, 'x-tl-range': range },
      body: blob });
    const j = await r.json().catch(() => ({}));
    if (j.id) ids.push(j.id);
    const where = (sf.folder && sf.folder.path) || '';
    row(t('gd_p_file'), !!j.id && /Files/.test(where), j.id
      ? esc(where) : String(j.error || ('HTTP ' + (j.status || r.status))).slice(0, 90));
  }catch(e){ row(t('gd_p_file'), false, String(e.message || e).slice(0, 90)); }

  /* 5. каталог: где файл оказался на самом деле и того ли он размера */
  if (ids.length){
    try{
      const r = await fetch(mediaFN() + '/media-health?verify=' + encodeURIComponent(ids[0]),
        { method: 'POST', headers: { Authorization: 'Bearer ' + token } });
      const v = await r.json().catch(() => ({}));
      if (!v.ok) row(t('gd_dir'), false, String(v.error || ('HTTP ' + r.status)).slice(0, 90));
      else {
        const sizeOk = !v.size || v.size === blob.size;
        const where = v.path || ((s1 && s1.folder ? s1.folder.root_name + ' / ' : '') + (v.parent_name || '—'));
        row(t('gd_dir'), !!v.in_archive && sizeOk,
          !v.in_archive ? t('gd_dir_bad') + ' · ' + esc(where)
          : !sizeOk ? t('gd_size_bad').replace('{A}', v.size).replace('{B}', blob.size)
          : esc(where));
      }
    }catch(e){ row(t('gd_dir'), false, String(e.message || e).slice(0, 90)); }
  } else row(t('gd_dir'), null, t('gd_dir_none'));

  /* 6. уборка: тестовые файлы на Диске не копим */
  if (ids.length){
    try{
      const r = await fetch(mediaFN() + '/media-health?cleanup=1', { method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
        body: JSON.stringify({ ids }) });
      const j = await r.json().catch(() => ({}));
      row(t('gd_p_clean'), (j.deleted || 0) === ids.length, (j.deleted || 0) + '/' + ids.length);
    }catch(e){ row(t('gd_p_clean'), false, String(e.message || e).slice(0, 90)); }
  }

  /* 7. подтверждение: спрашиваем media-commit про заведомо несуществующую
     запись. Правильный ответ — 404 NOT_FOUND; всё остальное означает, что
     последний шаг отправки сломан, и показывается вместе с телом ответа. */
  try{
    const r = await fetch(mediaFN() + '/media-commit', { method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
      body: JSON.stringify({ media_id: '00000000-0000-0000-0000-000000000000',
                             drive_file_id: 'selftest' }) });
    const body = await r.text().catch(() => '');
    const good = r.status === 404 && /NOT_FOUND/.test(body);
    row(t('gd_p_commit'), good, good ? t('gd_p_commit_ok')
      : t('gd_p_commit_bad') + ' · HTTP ' + r.status + (body ? ' ' + body.slice(0, 120) : ''));
  }catch(e){ row(t('gd_p_commit'), false, String(e.message || e).slice(0, 90)); }

  /* 8. вывод — и сразу переключаем настоящую отправку на рабочий путь */
  if (direct){ _mediaRelay = false; row(t('gd_p_way'), true, t('gd_p_direct')); }
  else if (relay){ _mediaRelay = true; row(t('gd_p_way'), true, t('gd_p_relay')); }
  else row(t('gd_p_way'), false, t('gd_p_none'));
  return { direct, relay };
}
async function mediaHealth(){
  if (!HAS_SB){ toast(t('media_sb_only'), 'err'); return; }
  const box = $('#gd-health'); if (box) box.textContent = '⏳ …';
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-health',
      { headers: { Authorization: 'Bearer ' + token } });
    const j = await r.json().catch(() => ({}));
    /* v1.07.70: строка отчёта; ok === null — серая точка «пропущено» */
    let h = '';
    const line = (k, ok, extra) =>
      `<div>${ic('dot', 'color:var(--' + (ok === null ? 'dim-2' : ok ? 'green' : 'red') + ')')} ${k}${extra ? ' — ' + extra : ''}</div>`;
    const row = (k, ok, extra) => line(k, ok, extra);
    const push = (k, ok, extra) => { h += line(k, ok, extra); if (box) box.innerHTML = h; };
    h += row(t('gd_db'), j.db && j.db.ok, j.db && (j.db.ok ? j.db.ms + ' ms' : esc(String(j.db.error || ''))));
    h += row(t('gd_auth'), j.auth && j.auth.ok,
      j.auth && j.auth.ok ? j.auth.ms + ' ms' : t('gd_not_conn'));
    if (j.drive && j.drive.ok){
      h += row(t('gd_acc'), true, esc(j.drive.account || ''));
      h += row(t('gd_used'), true, j.drive.used_gb + ' / ' + j.drive.limit_gb + ' GB');
    } else if (j.drive){
      h += row('Drive', false, esc(String(j.drive.error || '')).slice(0, 120));
    }
    if (j.folder && j.folder.id){
      h += row(t('gd_folder'), j.folder.ok !== false,
        esc(String(j.folder.name || '')) + ' · ' + esc(String(j.folder.id || '')));
      /* v1.07.78: наглядно — какая папка для фото, какая для документов */
      gdFolders = { root: { id: j.folder.id, name: j.folder.name || '', path: j.folder.name || '' },
                    photo: (j.paths && j.paths.photo) || null,
                    file:  (j.paths && j.paths.file)  || null,
                    invoice: (j.paths && j.paths.invoice) || null };   // v1.07.85
      gdNamesApply(gdNamesFrom(j));   // v1.08.36: подписи у полей — из того же ответа
      const fb = $('#gd-folders'); if (fb) fb.innerHTML = gdFoldersHtml();
      const chip = $('#gd-folder-chip');
      if (chip && j.folder.name){ chip.style.display = 'inline-flex';
        chip.innerHTML = ic('folder') + ' ' + esc(j.folder.name); }
    }
    if (j.write) h += row(t('gd_write'), j.write.ok, j.write.error ? esc(String(j.write.error)).slice(0, 120) : '');
    /* v1.07.64: свободное место — в настройки организации (видно менеджеру) */
    if (j.drive && j.drive.ok && j.drive.free_pct != null){
      const p = Number(j.drive.free_pct);
      h += row(t('gd_space'), p >= GD_LOW_PCT, Math.round(p) + '%');
      const o = state.data.org_settings || {};
      Object.assign(o, { gd_free_pct: p, gd_used_gb: +j.drive.used_gb, gd_limit_gb: +j.drive.limit_gb,
        gd_account: j.drive.account || '', gd_checked_at: new Date().toISOString() });
      state.data.org_settings = o; saveLocal();
    }
    if (box) box.innerHTML = h || '⛔';
    if (j.cfg){ Object.assign(gdCfg, j.cfg, { loaded: true }); }
    if (j.drive && j.drive.account) gdCfg.account = j.drive.account;
    /* v1.07.70: сквозная проверка — тем же путём, что и настоящее фото */
    const prow = (k, ok, extra) => push(k, ok, extra ? esc(String(extra)) : '');
    h += `<div class="gd-probe-h">${t('gd_fns')}</div>`; if (box) box.innerHTML = h;
    await gdFnCheck(prow);                       // v1.07.72: кто задеплоен и какой версии
    if (j.drive && j.drive.ok){
      h += `<div class="gd-probe-h">${t('gd_probe')}</div>`; if (box) box.innerHTML = h;
      await gdProbe(prow);
    }
  }catch(e){ if (box) box.innerHTML = '🔴 ' + esc(String(e.message || e)); }
}
/* =====================================================================
   v1.07.34: ДИАГНОСТИКА — интернет, БД, сессия, хранилище, функции и
   подключение к Google Drive (детали Drive — админу через media-health).
   ===================================================================== */
/* v1.07.67: карточка «Диагностика интерфейса». Сам движок живёт в
   uidiag.js — автономном модуле; если он не загрузился, карточка честно
   об этом пишет, а приложение работает как обычно. */
/* v1.07.77: настройки съёмки — у каждого свои, на своём телефоне */
function camCardHtml(){
  const md = camMode(), q = camQual(), sh = camSharpOn();
  const seg = (cur, val, lbl, fn) =>
    `<button class="${cur === val ? 'on' : ''}" onclick="App.${fn}('${val}')">${lbl}</button>`;
  /* подпись и переключатель — в столбик: подсказки длинные, в две колонки
     они на 414 px сминаются в узкий столбец из одного слова */
  return `<div class="card">
    <div style="font-weight:900;margin-bottom:6px">${ic('camera')} ${t('cam_card')}</div>
    <div class="cam-set">
      <b>${t('cam_mode_lbl')}</b>
      <div class="tiny">${md === 'quick' ? t('cam_mode_quick_h') : t('cam_mode_full_h')}</div>
      <div class="lang-seg cam-seg">
        ${seg(md, 'full', t('cam_mode_full'), 'camMode')}
        ${seg(md, 'quick', t('cam_mode_quick'), 'camMode')}
      </div>
    </div>
    <div class="cam-set">
      <b>${t('cam_q_lbl')}</b>
      <div class="tiny">${t('cam_q_' + q + '_h')}</div>
      <div class="lang-seg cam-seg cam-q">
        ${seg(q, 'eco', t('cam_q_eco'), 'camQ')}
        ${seg(q, 'std', t('cam_q_std'), 'camQ')}
        ${seg(q, 'hi', t('cam_q_hi'), 'camQ')}
        ${seg(q, 'orig', t('cam_q_orig'), 'camQ')}
      </div>
    </div>
    <div class="cam-set">
      <b>${ic('camera')} ${t('cam_hdr_t')}</b>
      <div class="tiny">${t('cam_hdr_h')}</div>
    </div>
    <button class="btn btn-green sm" style="margin-top:10px" onclick="App.camNative()">${ic('camera')} ${t('cam_native_btn')}</button>
    <div class="tiny" style="margin:4px 0 6px">${t('cam_native_h')}</div>
    <label class="opt ${camUsmOn() ? 'on' : ''}">
      <input type="checkbox" ${camUsmOn() ? 'checked' : ''} onchange="App.camUsm(this.checked)"> ${t('cam_usm')}</label>
    <div class="tiny" style="margin-bottom:6px">${t('cam_usm_h')}</div>
    <label class="opt ${sh ? 'on' : ''}" style="margin-top:10px">
      <input type="checkbox" ${sh ? 'checked' : ''} onchange="App.camSharp(this.checked)"> ${t('cam_sharp_chk')}
    </label>
    <div class="tiny" style="margin-top:6px">${t('cam_hint')}</div>
  </div>`;
}
function uiDiagCardHtml(){
  const on = (() => { try { return localStorage.getItem('techlog_uidiag') === '1'; } catch(e){ return false; } })();
  return `<div class="card">
    <div style="font-weight:900;margin-bottom:6px">${ic('layers')} ${t('ui_card')}</div>
    <div class="tiny" style="margin-bottom:8px">${t('ui_hint')}</div>
    <label class="opt ${on ? 'on' : ''}">
      <input type="checkbox" ${on ? 'checked' : ''} onchange="App.uiDiagToggle(this.checked)"> ${t('ui_chk')}
    </label>
    <button class="btn btn-blue sm" style="margin-top:8px" onclick="App.uiDiagRun()">${ic('search')} ${t('ui_run')}</button>
    <button class="btn btn-ghost sm" style="margin-top:8px" onclick="App.uiDiagAll()">${ic('layers')} ${t('ui_all')}</button>
    <div class="tiny" style="margin-top:6px">${t('ui_keys')}</div>
  </div>`;
}
function diagCardHtml(){
  return `<div class="card" id="dg-card">
    <div style="font-weight:900;margin-bottom:6px">${ic('flask')} ${t('diag_card')}</div>
    <button class="btn btn-blue" onclick="App.runDiag()">${ic('play')} ${t('diag_run')}</button>
    <div id="dg-out" class="tiny" style="margin-top:8px"></div>
  </div>`;
}
async function runDiag(){
  const out = $('#dg-out'); if (!out) return;
  out.innerHTML = '⏳ …';
  const rows = [];
  const paint = () => { out.innerHTML = rows.join(''); };
  const row = (name, ok, extra) => {
    rows.push(`<div>${ic('dot', 'color:var(--' + (ok === null ? 'dim-2' : ok ? 'green' : 'red') + ')')} ${name}${extra ? ' — ' + esc(String(extra)) : ''}</div>`);
    paint();
  };
  rows.length = 0; paint();
  /* 1. интернет */
  try{
    const t0 = Date.now();
    await fetch('version.json?d=' + Date.now(), { cache: 'no-store' });
    row(t('diag_net'), true, (Date.now() - t0) + ' ms');
  }catch(e){ row(t('diag_net'), false, e.message || e); }
  /* 1б. внешние сервисы карт: тайлы OSM (<img> — без CORS) и геокодер
     Nominatim — оба нужны экрану «Карта» и подстановке адресов. */
  await new Promise(res => {
    const t0 = Date.now(); const im = new Image(); let done = false;
    const fin = ok => { if (done) return; done = true;
      row(t('diag_osm'), ok, ok ? (Date.now() - t0) + ' ms' : t('diag_ext_err')); res(); };
    im.onload = () => fin(true); im.onerror = () => fin(false);
    setTimeout(() => fin(false), 8000);
    im.src = 'https://tile.openstreetmap.org/3/2/3.png?d=' + Date.now();
  });
  try{
    const t0 = Date.now();
    const r = await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q=Atlanta',
      { headers: { 'Accept': 'application/json' } });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    await r.json();
    row(t('diag_geo'), true, (Date.now() - t0) + ' ms');
  }catch(e){ row(t('diag_geo'), false, e.message || e); }
  if (!HAS_SB){
    [t('diag_db'), t('diag_auth'), t('diag_store'), t('diag_fn')]
      .forEach(n => row(n, null, t('diag_skip')));
    return;
  }
  /* 2. база */
  try{
    const t0 = Date.now();
    const { error } = await state.sb.from('org_settings').select('id').limit(1);
    if (error) throw error;
    row(t('diag_db'), true, (Date.now() - t0) + ' ms');
  }catch(e){ row(t('diag_db'), false, e.message || e); }
  /* 3. сессия */
  try{
    const { data } = await state.sb.auth.getSession();
    row(t('diag_auth'), !!(data && data.session),
      data && data.session ? ((state.user && state.user.login) || 'ok') : t('diag_no_sess'));
  }catch(e){ row(t('diag_auth'), false, e.message || e); }
  /* 4. bucket миниатюр */
  try{
    const { error } = await state.sb.storage.from('media-thumbs').list('', { limit: 1 });
    if (error) throw error;
    row(t('diag_store'), true, '');
  }catch(e){ row(t('diag_store'), false, (e.message || e) + ' · ' + t('diag_sql31')); }
  /* 4б. Bouncie GPS — через одноимённую edge-функцию: ping отвечает без
     прав, живой список машин — менеджеру и админу (реальный поход в API). */
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/bouncie?ping=1',
      { headers: { Authorization: 'Bearer ' + token } });
    if (r.status === 404) throw new Error(t('diag_deploy'));
    const j = await r.json().catch(() => ({}));
    row(t('diag_bn_fn'), j.fn === 'bouncie', j.ver ? 'v' + j.ver : '');
    if (isManager()){
      const t0 = Date.now();
      const v = await bnFetch('?vehicles=1');
      if (v && Array.isArray(v.vehicles))
        row(t('diag_bn_api'), true, v.vehicles.length + ' ' + t('diag_veh') + ' · ' + (Date.now() - t0) + ' ms');
      else
        row(t('diag_bn_api'), false, String((v && (v.error || v.err)) || BN.err || t('diag_bn_off')).slice(0, 60));
    }
  }catch(e){
    const noFn = (e && (e.name === 'TypeError' || /Failed to fetch|NetworkError/i.test(e.message || '')));
    row(t('diag_bn_fn'), false, noFn ? t('diag_deploy') : (e.message || e));
  }
  /* 5. функции + Google Drive */
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-health',
      { headers: { Authorization: 'Bearer ' + token } });
    if (r.status === 404) throw new Error(t('diag_deploy'));
    if (r.status === 403){ row(t('diag_fn'), true, t('diag_fn_admin')); return; }
    row(t('diag_fn'), true, '');
    if (isAdmin()){
      const j = await r.json().catch(() => ({}));
      row(t('gd_auth'), !!(j.auth && j.auth.ok),
        j.auth && j.auth.ok ? j.auth.ms + ' ms' : t('gd_not_conn'));
      if (j.drive && j.drive.ok){
        row(t('gd_acc'), true, j.drive.account || '');
        row(t('gd_used'), true, j.drive.used_gb + ' / ' + j.drive.limit_gb + ' GB');
      } else if (j.drive){
        row('Google Drive', false, String(j.drive.error || '').slice(0, 90));
      }
      if (j.write) row(t('gd_write'), !!j.write.ok,
        j.write.error ? String(j.write.error).slice(0, 90) : '');
      /* v1.07.70: тот же сквозной прогон, что и в «Тесте соединения» */
      await gdFnCheck(row);
      if (j.drive && j.drive.ok) await gdProbe(row);
    }
  }catch(e){
    /* v1.07.56: недеплоенная edge-функция даёт сетевой TypeError («Failed
       to fetch») без HTTP-кода — показываем ту же инструкцию, что и 404. */
    const noFn = (e && (e.name === 'TypeError' || /Failed to fetch|NetworkError/i.test(e.message || '')));
    row(t('diag_fn'), false, noFn ? t('diag_deploy') : (e.message || e));
  }
}
/* фейд вместо обрубания: класс вешается только реально обрезанным текстам */
function updateFadeClips(){
  /* v1.07.67: читаем геометрию всех элементов сначала, пишем классы потом —
     иначе чередование чтение/запись даёт принудительный пересчёт лэйаута
     на каждом элементе (layout thrashing). */
  const els = [...document.querySelectorAll('.brand .name,.brand .sub,.tabbar .tab span')];
  const need = els.map(e => e.scrollWidth > e.clientWidth + 1);
  els.forEach((e, i) => e.classList.toggle('fade-clip', need[i]));
}
(function initFadeClips(){
  /* v1.07.67: дебаунс «взвёл и жду» вместо сбрасывающегося. Старый вариант
     (clearTimeout на каждую мутацию) при потоке перерисовок откладывался
     бесконечно, а затем стрелял пачкой — та же ловушка, что уже ловили в
     desktop.js. Плюс сама проверка идёт в rAF, вне обработчика мутаций. */
  let armed = false;
  const kick = () => {
    if (armed) return;
    armed = true;
    setTimeout(() => { armed = false; requestAnimationFrame(updateFadeClips); }, 80);
  };
  addEventListener('resize', kick, { passive: true });
  const root = document.getElementById('app') || document.body;
  new MutationObserver(kick).observe(root, { childList: true, subtree: true });
  kick();
})();
initMedia();
bnInit();   // v1.08.32: фоновый опрос GPS-трекинга Bouncie

/* =====================================================================
   v1.07.32: БЭКАП ДАННЫХ — интегрирован в приложение (Настройки, админ).
   Выгрузка: все таблицы постранично + учётки (RPC) + секреты (по галочке)
   в один JSON. Загрузка: учётки → таблицы в порядке зависимостей FK,
   пачками через admin_restore_rows; дубли отсекает Postgres
   (ON CONFLICT DO NOTHING), ошибки — построчно в экранный лог с
   выгрузкой в .txt. Журналы выгружаются, но кнопкой не восстанавливаются.
   ===================================================================== */
const BK_TABLES = ['profiles','counterparties','complexes','aux_equipment','work_types',
  'equipment_types','size_types','extra_works','product_types','price_list',
  'counterparty_prices','equipment_stock','org_settings','hidden_staff',
  'code_requests','complex_code_history','proposals','repairs','jobs','placements',
  'ext_requests','media','equip_moves','acc_settings'];   // v1.08.27: журнал после placements — при восстановлении FK уже на месте; v1.08.39: + acc_settings
const BK_EXPORT_ONLY = ['audit_log','tech_log'];
const BK_PAGE = 1000, BK_CHUNK = 300;
let bkLogLines = null;

function bkStamp(){ const d = new Date(), p = n => String(n).padStart(2,'0');
  return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}`; }
function bkLog(mark, msg){
  bkLogLines = bkLogLines || [];
  const s = `${new Date().toLocaleTimeString()} ${mark} ${msg}`;
  bkLogLines.push(s);
  const pre = $('#bk-log');
  if (pre){ pre.style.display = 'block'; pre.textContent += s + '\n'; pre.scrollTop = pre.scrollHeight; }
  const btn = $('#bk-save'); if (btn) btn.style.display = 'inline-flex';
}
function bkDownload(blob, name){
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob); a.download = name;
  document.body.appendChild(a); a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 4000);
}
function bkSaveLog(){
  if (!bkLogLines) return;
  bkDownload(new Blob([bkLogLines.join('\n')], { type: 'text/plain;charset=utf-8' }),
    `techlog-${bkStamp()}-log.txt`);
}
const bkNoRpc = e => /PGRST202|Could not find the function|schema cache/i
  .test(String((e && e.message) || e));
function bkBusy(v){ ['#bk-exp', '#bk-imp'].forEach(s => { const b = $(s); if (b) b.disabled = !!v; }); }

async function bkFetchAll(tb){
  if (!HAS_SB){                                   // демо: из локального состояния
    if (tb === 'org_settings') return [state.data.org_settings];
    if (tb === 'audit_log' || tb === 'tech_log')
      return (state.data.audit_log || []).filter(r => (r.src || 'doc') === (tb === 'tech_log' ? 'tech' : 'doc'));
    return (state.data[tb] || []).slice();
  }
  const out = []; let from = 0;
  for (;;){
    let q = state.sb.from(tb).select('*');
    q = (tb === 'audit_log' || tb === 'tech_log')
      ? q.order('at', { ascending: true }) : q.order('id', { ascending: true });
    const { data, error } = await q.range(from, from + BK_PAGE - 1);
    if (error){
      if (/does not exist|42P01/i.test(error.message)) return null;   // таблицы ещё нет
      throw new Error(error.message);
    }
    out.push(...data);
    if (data.length < BK_PAGE) break;
    from += BK_PAGE;
  }
  return out;
}
async function bkExport(){
  const withSec = !!(($('#bk-sec') || {}).checked);
  bkLogLines = [`${t('bk_log_export')} ${new Date().toLocaleString()}`];
  const pre = $('#bk-log'); if (pre){ pre.style.display = 'block'; pre.textContent = ''; }
  bkBusy(true);
  try{
    const counts = {}; const parts = []; let first = true;
    const meta = { app: 'TechLog', kind: 'backup', app_version: APP_VERSION,
      exported_at: new Date().toISOString(), by: (state.user && state.user.login) || '?' };
    parts.push('{"meta":' + JSON.stringify(meta) + ',"tables":{');
    for (const tb of [...BK_TABLES, ...BK_EXPORT_ONLY]){
      try{
        const rows = await bkFetchAll(tb);
        if (rows === null){ bkLog('·', tb + ': ' + t('bk_no_table')); continue; }
        parts.push((first ? '' : ',') + JSON.stringify(tb) + ':' + JSON.stringify(rows));
        first = false; counts[tb] = rows.length;
        bkLog('✔', `${tb}: ${rows.length}`);
      }catch(e){ bkLog('⛔', `${tb}: ${e.message || e}`); }
    }
    parts.push('}');
    if (HAS_SB){
      try{
        const { data, error } = await state.sb.rpc('admin_export_auth_users');
        if (error) throw error;
        parts.push(',"auth_users":' + JSON.stringify(data || []));
        counts.auth_users = (data || []).length;
        bkLog('✔', `auth_users: ${counts.auth_users} (bcrypt)`);
      }catch(e){ bkLog('⛔', 'auth_users: ' + (bkNoRpc(e) ? t('bk_need_sql') : (e.message || e))); }
      if (withSec){
        try{
          const { data, error } = await state.sb.rpc('admin_export_secrets');
          if (error) throw error;
          parts.push(',"secrets":' + JSON.stringify(data || []));
          bkLog('✔', `secrets: ${(data || []).length} — ${t('bk_secrets_warn')}`);
        }catch(e){ bkLog('⛔', 'secrets: ' + (e.message || e)); }
      }
    }
    parts.push('}');
    const name = `techlog-backup-${bkStamp()}.json`;
    bkDownload(new Blob(parts, { type: 'application/json' }), name);
    bkLog('✔', t('bk_done_file') + ': ' + name);
    audit('backup_export', 'system', 'backup', { counts, with_secrets: withSec });
  } finally { bkBusy(false); }
}
function bkImportPick(){
  if (!HAS_SB){ toast(t('bk_demo_imp'), 'err'); return; }
  const inp = document.createElement('input');
  inp.type = 'file'; inp.accept = 'application/json,.json';
  inp.onchange = () => {
    const f = inp.files && inp.files[0]; if (!f) return;
    if (!confirm(t('bk_confirm'))) return;
    bkImportFile(f);
  };
  inp.click();
}
async function bkImportFile(file){
  bkLogLines = [`${t('bk_log_import')} ${new Date().toLocaleString()}`];
  const pre = $('#bk-log'); if (pre){ pre.style.display = 'block'; pre.textContent = ''; }
  const withSec = !!(($('#bk-sec') || {}).checked);
  bkBusy(true);
  try{
    let b;
    try{
      bkLog('·', t('bk_reading') + ' ' + file.name + ' …');
      b = JSON.parse(await file.text());
      if (!b || !b.tables) throw new Error(t('bk_notfile'));
    }catch(e){ bkLog('⛔', String(e.message || e)); return; }
    bkLog('·', `${t('bk_from')} ${(b.meta && b.meta.exported_at) || '?'} (${t('bk_by')}: ${(b.meta && b.meta.by) || '?'})`);

    let tIns = 0, tSkip = 0, tErr = 0;
    /* 1. учётные записи — раньше профилей (FK profiles.id → auth.users.id) */
    if (Array.isArray(b.auth_users) && b.auth_users.length){
      let c = 0, ex = 0;
      for (const u of b.auth_users){
        try{
          const { data, error } = await state.sb.rpc('admin_restore_auth_user', { p: u });
          if (error) throw error;
          if (data === 'created') c++; else ex++;
        }catch(e){
          tErr++;
          bkLog('⛔', `auth_users ${u.email || u.id}: ${bkNoRpc(e) ? t('bk_need_sql') : (e.message || e)}`);
          if (bkNoRpc(e)) return;
        }
      }
      bkLog('✔', `auth_users: ${t('bk_users_c')} ${c}, ${t('bk_users_e')} ${ex}`);
    }
    /* 2. таблицы в порядке зависимостей, пачками; дубли отсекает БД */
    for (const tb of BK_TABLES){
      const rows = b.tables[tb];
      if (!Array.isArray(rows) || !rows.length) continue;
      let ins = 0, skip = 0; const errs = [];
      for (let i = 0; i < rows.length; i += BK_CHUNK){
        try{
          const { data, error } = await state.sb.rpc('admin_restore_rows',
            { p_table: tb, p_rows: rows.slice(i, i + BK_CHUNK) });
          if (error) throw error;
          ins += data.inserted; skip += data.skipped;
          for (const e of (data.errors || [])) errs.push(e);
        }catch(e){
          if (bkNoRpc(e)){ bkLog('⛔', t('bk_need_sql')); return; }
          errs.push({ row: `#${i}–${i + BK_CHUNK}`, error: String(e.message || e) });
        }
      }
      tIns += ins; tSkip += skip; tErr += errs.length;
      bkLog(errs.length ? '⛔' : '✔',
        `${tb}: ${t('bk_added')} ${ins}, ${t('bk_dupes')} ${skip}, ${t('bk_errs')} ${errs.length}`);
      for (const e of errs) bkLog('⛔', `   ${tb} [${e.row}]: ${e.error}`);
    }
    /* 3. секреты — только по явной галочке */
    if (withSec && Array.isArray(b.secrets) && b.secrets.length){
      try{
        const { data, error } = await state.sb.rpc('admin_restore_secrets', { p: b.secrets });
        if (error) throw error;
        bkLog('✔', 'secrets: ' + data);
      }catch(e){ tErr++; bkLog('⛔', 'secrets: ' + (e.message || e)); }
    }
    if (b.tables.audit_log || b.tables.tech_log) bkLog('·', t('bk_journal_skip'));
    bkLog('✔', `${t('bk_total')}: ${t('bk_added')} ${tIns}, ${t('bk_dupes')} ${tSkip}, ${t('bk_errs')} ${tErr}`);
    audit('backup_restore', 'system', 'backup',
      { inserted: tIns, skipped: tSkip, errors: tErr, file: file.name });
    try{ if (App.sync) await App.sync(); }catch(e){}
    render();
  } finally { bkBusy(false); }
}
function backupCardHtml(){
  if (!isAdmin()) return '';
  return `<div class="card" id="bk-card">
    <div style="font-weight:900;margin-bottom:6px">${ic('save')} ${t('bk_card')}</div>
    <div class="tiny" style="margin-bottom:8px">${t('bk_intro')}</div>
    <div class="btn-rowpp" style="margin:0">
      <button id="bk-exp" class="btn btn-blue" onclick="App.bkExport()">${ic('save')} ${t('bk_export')}</button>
      <button id="bk-imp" class="btn btn-ghost" onclick="App.bkImportPick()">${ic('download')} ${t('bk_import')}</button>
    </div>
    <label class="opt" style="margin:8px 0 0">
      <input type="checkbox" id="bk-sec"> ${t('bk_secrets')}</label>
    <pre id="bk-log" style="display:none;max-height:260px;overflow:auto;background:#17232A;border:2px solid var(--line);border-radius:12px;padding:10px 12px;font-size:12px;white-space:pre-wrap;margin-top:8px"></pre>
    <button id="bk-save" class="btn btn-ghost sm" style="display:none;margin-top:6px" onclick="App.bkSaveLog()">${ic('download')} ${t('bk_savelog')}</button>
    <details style="margin-top:8px"><summary class="tiny">${t('bk_new_proj')}</summary>
      <div class="tiny" style="margin-top:6px;line-height:1.5">${(state.lang || 'ru') !== 'en' ? `
        1. В новом проекте выполните ОДИН файл supabase/${DB_SQL_FILE} — это вся схема и все обновления разом.<br>
        2. Зарегистрируйтесь под <b>временным</b> логином (не совпадающим ни с одним старым) и назначьте себе admin через SQL-редактор.<br>
        3. Загрузите бэкап с галочкой секретов: учётки встанут первыми — сотрудники войдут <b>старыми паролями</b>.<br>
        4. Войдите под прежним логином, временного удалите или заблокируйте.<br>
        Журналы кнопкой не восстанавливаются (сниппет — в update-to-1_07_32.sql). Миниатюры фото в новый проект не переносятся; полноразмеры в Google Drive остаются доступны.` : `
        1. In the new project run ONE file, supabase/${DB_SQL_FILE} — the whole schema and every update at once.<br>
        2. Register with a <b>temporary</b> login (matching none of the old ones) and grant yourself admin in the SQL editor.<br>
        3. Load the backup with the secrets checkbox on: accounts are restored first — staff sign in with their <b>old passwords</b>.<br>
        4. Sign in with your previous login, then delete or block the temporary one.<br>
        Journals are not restored by the button (the snippet is in update-to-1_07_32.sql). Photo thumbnails do not move to the new project; full-size files on Google Drive stay available.`}
      </div>
    </details>
  </div>`;
}

/* =====================================================================
   v1.07.05: перетаскивание карточек дня жестом — зажать и тянуть ▲▼
   Работает и пальцем (long-press ~0.34 c), и мышью. Кнопки ▲▼ остаются.
   ===================================================================== */
let dnd = null;              // { el, id, pid, x, y, active, timer, staticTop, grabDY }
let dndClickBlock = 0;       // подавить клик, случившийся сразу после drag
function dndItems(){ return [...document.querySelectorAll('#app .item[data-drag-id]')]; }
/* v1.07.67: блокирующий touchmove — только на перетаскиваемых карточках
   и только на главной. touchmove всегда приходит в элемент, на котором
   начался touchstart, поэтому слушателя на карточке достаточно. */
function dndTouchMove(e){ if (dnd && dnd.active && e.cancelable) e.preventDefault(); }
function dndBindTouch(){
  try{
    if (!state.user || state.screen !== 'home') return;
    document.querySelectorAll('#app .item[data-drag-id][data-can="1"]').forEach(el => {
      if (el.__tlTouch) return;
      el.__tlTouch = 1;
      el.addEventListener('touchmove', dndTouchMove, { passive: false });
    });
  }catch(e){}
}
function dndCalib(){
  if (!dnd) return;
  const tr = dnd.el.style.transform;
  dnd.el.style.transform = 'none';
  const r = dnd.el.getBoundingClientRect();
  dnd.staticTop = r.top;
  dnd.staticLeft = r.left;                                  // v1.07.20: двухколоночная сетка ПК
  dnd.el.style.transform = tr;
}
function dndPlace(clientX, clientY){
  dnd.el.style.transform =
    `translate(${(clientX - dnd.grabDX) - dnd.staticLeft}px, ${(clientY - dnd.grabDY) - dnd.staticTop}px)`;
}
function dndActivate(){
  if (!dnd || dnd.active) return;
  dnd.active = true;
  try{ dnd.el.setPointerCapture(dnd.pid); }catch(e){}
  dnd.el.classList.add('dragging');
  document.body.classList.add('dnd-on');
  dndCalib();
  dnd.grabDY = dnd.y - dnd.staticTop;
  dnd.grabDX = dnd.x - dnd.staticLeft;
  dndPlace(dnd.x, dnd.y);
  navigator.vibrate?.(30);
}
function dndDown(e){
  if (dnd || state.screen !== 'home') return;
  if (e.button != null && e.button !== 0) return;
  const el = e.target.closest('.item[data-drag-id]');
  if (!el || el.dataset.can !== '1') return;
  if (e.target.closest('button,select,input,a,textarea,.key-copy')) return;
  /* v1.07.22: у мыши нет конфликта «скролл или перенос» — таймер удержания
     не нужен: обычный клик открывает карточку, а движение с зажатой кнопкой
     сразу начинает перенос (см. dndMove). Пальцу — прежний long-press 340 мс. */
  const mouse = e.pointerType === 'mouse';
  dnd = { el, id: el.dataset.dragId, pid: e.pointerId, x: e.clientX, y: e.clientY,
          mouse, active: false, timer: mouse ? 0 : setTimeout(dndActivate, 340) };
}
function dndMove(e){
  if (!dnd) return;
  if (!dnd.active){
    const th = dnd.mouse ? 6 : 8;
    if (Math.abs(e.clientY - dnd.y) > th || Math.abs(e.clientX - dnd.x) > th){
      if (!dnd.mouse){ clearTimeout(dnd.timer); dnd = null; return; } // палец «поехал» до long-press — это скролл
      dndActivate();  // v1.07.22: мышь потянула карточку — начинаем перенос и ведём её этим же событием
    } else return;
  }
  if (e.cancelable) e.preventDefault();
  // автопрокрутка страницы у верхнего/нижнего края
  if (e.clientY < 90){ window.scrollBy(0, -14); dndCalib(); }
  else if (e.clientY > window.innerHeight - 110){ window.scrollBy(0, 14); dndCalib(); }
  dndPlace(e.clientX, e.clientY);
  /* v1.07.20: цель ищем и по X (двухколоночная сетка ПК), и только в СВОЁМ
     списке — карточка работы не должна «впрыгивать» в список пикапов */
  const over = dndItems().find(o => {
    if (o === dnd.el || o.parentNode !== dnd.el.parentNode) return false;
    const r = o.getBoundingClientRect();
    return e.clientY >= r.top && e.clientY <= r.bottom
        && e.clientX >= r.left && e.clientX <= r.right;
  });
  if (over){
    const r = over.getBoundingClientRect();
    const midX = r.left + r.width / 2, midY = r.top + r.height / 2;
    /* в колонке решаем по вертикали; в ряду сетки (палец у вертикальной
       середины соседа) — по горизонтали, порядок чтения слева-направо */
    const before = (Math.abs(e.clientY - midY) >= r.height * 0.22)
      ? e.clientY < midY
      : e.clientX < midX;
    const p = over.parentNode;
    if (before && over.previousElementSibling !== dnd.el){
      p.insertBefore(dnd.el, over); dndCalib(); dndPlace(e.clientX, e.clientY);
    } else if (!before && over.nextElementSibling !== dnd.el){
      p.insertBefore(dnd.el, over.nextElementSibling); dndCalib(); dndPlace(e.clientX, e.clientY);
    }
  }
}
function dndFinish(apply){
  if (!dnd) return;
  clearTimeout(dnd.timer);
  const was = dnd.active;
  if (was){
    dnd.el.classList.remove('dragging');
    dnd.el.style.transform = '';
    document.body.classList.remove('dnd-on');
    dndClickBlock = Date.now() + 350;
  }
  const ids = (was && apply) ? [...new Set(dndItems().map(el => el.dataset.dragId))] : null;
  dnd = null;
  if (ids) applyDayOrder(ids);
  else if (was) render(); // отмена — вернуть как было
}
async function applyDayOrder(ids){
  for (let i = 0; i < ids.length; i++){
    const j = state.data.jobs.find(x => x.id === ids[i]);
    if (!j || (j.sort_order || 0) === i) continue;
    if (canReorder(j)){ try{ await saveJobPatch(j, { sort_order: i }); }catch(e){ toast('⛔ ' + rpcFail(e, 'board_job_flags'), 'err'); break; } }
    else j.sort_order = i; // чужие — только локально для отображения
  }
  navigator.vibrate?.(15);
  dlog('dnd: порядок дня обновлён перетаскиванием');
  render();
}
function initDragSort(){
  document.addEventListener('pointerdown', dndDown, { passive: true });
  document.addEventListener('pointermove', dndMove, { passive: false });
  document.addEventListener('pointerup', () => dndFinish(true));
  document.addEventListener('pointercancel', () => dndFinish(false));
  window.addEventListener('blur', () => dndFinish(false));   // v1.07.22: мышь отпущена вне окна / alt-tab — не зависаем в захвате
  /* v1.07.20: на тач-устройствах прокрутку останавливает только touchmove.
     preventDefault на pointermove скролл НЕ отменяет — браузер начинал
     прокрутку и стрелял pointercancel, убивая перетаскивание на первом же
     движении пальца. Гасим прокрутку, только пока карточка реально «в руке».
     v1.07.67: раньше здесь висели ДВА одинаковых блокирующих touchmove на
     document (и два contextmenu — дубль). Блокирующий touchmove на document
     означает, что палец на ЛЮБОМ экране ждёт главный поток. Теперь
     обработчик вешается на сами карточки при отрисовке (dndBindTouch):
     перетаскивание работает как раньше, а настройки/справочники/отчёты
     прокручиваются на потоке композитора. */
  document.addEventListener('contextmenu', e => { if (dnd) e.preventDefault(); });
  document.addEventListener('click', e => {
    if (Date.now() < dndClickBlock){ e.preventDefault(); e.stopPropagation(); }
  }, true);
}

/* ---------- v1.07.05: вкладки справочников — drag-скролл мышью ----------
   (пальцем полоса вкладок скроллится нативно; стрелки ‹ › — App.dirTabsScroll) */
let tdrag = null, tabsClickBlock = 0;
function initTabsDrag(){
  document.addEventListener('pointerdown', e => {
    if (e.pointerType !== 'mouse') return;
    const el = e.target.closest('.tabs');
    if (!el || el.scrollWidth <= el.clientWidth + 4) return;
    tdrag = { el, x: e.clientX, left: el.scrollLeft, moved: false, pid: e.pointerId };
  }, { passive: true });
  document.addEventListener('pointermove', e => {
    if (!tdrag) return;
    const dx = e.clientX - tdrag.x;
    if (!tdrag.moved && Math.abs(dx) > 6){
      tdrag.moved = true;
      tdrag.el.classList.add('grabbing');
      try{ tdrag.el.setPointerCapture(tdrag.pid); }catch(_){}
    }
    if (tdrag.moved) tdrag.el.scrollLeft = tdrag.left - dx;
  });
  const tEnd = () => {
    if (!tdrag) return;
    tdrag.el.classList.remove('grabbing');
    if (tdrag.moved) tabsClickBlock = Date.now() + 300;
    tdrag = null;
  };
  document.addEventListener('pointerup', tEnd);
  document.addEventListener('pointercancel', tEnd);
  document.addEventListener('click', e => {
    if (Date.now() < tabsClickBlock && e.target.closest('.tabs')){ e.preventDefault(); e.stopPropagation(); }
  }, true);
}

/* =====================================================================
   v1.05: коды доступа — callbox/ворота, заявки админу, история
   ===================================================================== */
function codeLineHtml(cx, compact){
  const parts = [];
  if (cx.access_code) parts.push(`<button class="key-copy" onclick="event.stopPropagation();App.copyText('${esc(cx.access_code)}')">${ic('key')} ${esc(cx.access_code)}</button>`);
  if (cx.callbox_code) parts.push(`<button class="key-copy" onclick="event.stopPropagation();App.copyText('${esc(cx.callbox_code)}')">${cx.callbox_gate ? ic('gate') : ic('callbox')} ${esc(cx.callbox_code)}</button>`);
  return parts.join(compact ? ' · ' : ' &nbsp; ');
}
function cxHistory(cxId){
  return (state.data.complex_code_history || [])
    .filter(h => h.complex_id === cxId)
    .sort((a,b) => String(b.changed_at||'').localeCompare(String(a.changed_at||'')));
}
function lastCodeMeta(cxId){
  const h = cxHistory(cxId)[0];
  return h ? { date: h.changed_at, by: h.changed_by } : null;
}
function firstSeenOf(cxId, field, value){
  if (!value) return null;
  const list = cxHistory(cxId).filter(h => h.field === field && h.new_value === value);
  return list.length ? list[list.length - 1] : null;
}
function firstSeenLine(cxId, field, value){
  const f = firstSeenOf(cxId, field, value);
  if (!f) return '';
  return `<span class="tiny">${t('since')} ${fmtDMY(String(f.changed_at).slice(0,10))} · ${esc(profName(f.changed_by))}</span>`;
}
function pendingCodeRequests(){
  return (state.data.code_requests || []).filter(r => r.status === 'pending');
}

/* модалка истории кодов */
