function szById(id){ return (state.data.size_types||[]).find(s=>s.id===id); }
function ewById(id){ return (state.data.extra_works||[]).find(s=>s.id===id); }
function ptById(id){ return (state.data.product_types||[]).find(s=>s.id===id); }

/* =====================================================================
   v1.07.84: В БЛАНК НЕ ДОЛЖНА ПОПАДАТЬ КИРИЛЛИЦА. Заметки переводятся
   (v1.07.83), названия справочников дают английский вариант через слэш
   (enName), но имена сотрудников, контрагентов, комплексов и адреса
   переводить нечем — а helvetica в jsPDF кириллицу не рисует вовсе:
   в PDF на её месте пусто или мусор. Такие строки транслитерируем.
   ===================================================================== */
const TRANSLIT = {
  а:'a', б:'b', в:'v', г:'g', д:'d', е:'e', ё:'e', ж:'zh', з:'z', и:'i', й:'y',
  к:'k', л:'l', м:'m', н:'n', о:'o', п:'p', р:'r', с:'s', т:'t', у:'u', ф:'f',
  х:'kh', ц:'ts', ч:'ch', ш:'sh', щ:'shch', ъ:'', ы:'y', ь:'', э:'e', ю:'yu', я:'ya',
  і:'i', ї:'yi', є:'ye', ґ:'g'
};
function translit(s){
  const str = String(s == null ? '' : s);
  if (!CYR_RE.test(str)) return str;
  let out = '';
  for (const ch of str){
    const low = ch.toLowerCase();
    const rep = TRANSLIT[low];
    if (rep === undefined){ out += ch; continue; }
    out += (ch === low) ? rep : (rep.charAt(0).toUpperCase() + rep.slice(1));
  }
  return out;
}
/* Одна точка контроля: подменяем doc.text у готового бланка, и что бы в
   него ни писали дальше — кириллицы там не будет. */
function pdfLatinize(doc){
  if (!doc || doc.__latin) return doc;
  const orig = doc.text.bind(doc);
  doc.text = function(txt, ...rest){
    const f = (x) => (typeof x === 'string' ? translit(x) : x);
    return orig(Array.isArray(txt) ? txt.map(f) : f(txt), ...rest);
  };
  doc.__latin = true;
  return doc;
}
/* =====================================================================
   v1.07.86 · НУМЕРАЦИЯ ДОКУМЕНТОВ И ИМЁН ФАЙЛОВ — КОНСТРУКТОРОМ.
   Админ сам собирает номер из кусочков: тип документа, дата, контрагент,
   комплекс, юнит, инициалы сотрудника, порядковый номер. Не нужны
   инициалы — убрал из шаблона, и их нет. Тот же конструктор отдельно
   для имён фото и вложений на Диске (его применяет media-begin).
   Пустые кусочки выпадают вместе с лишними разделителями.
   ===================================================================== */
const DOC_FMT_DEF  = '{TYPE}-{DATE}-{CX}-{UNIT}-{SEQ}';
const FILE_FMT_DEF = '{DATE}_{CX}_{UNIT}_{NAME}_{SEQ}';
const DOC_TOKENS  = ['TYPE','DATE','YEAR','CP','CX','UNIT','TECH','WT','SEQ'];
const FILE_TOKENS = ['DATE','YEAR','CP','CX','UNIT','TECH','WT','NAME','KIND','SEQ'];
/* метки типов: работа, пропозал, пикап, продление */
const DOC_TYPE_TAG = { job: 'WORK', prop: 'PROP', pick: 'PICK', ext: 'LONG', rep: 'REP' };

function docFmt(){ return String(((state.data && state.data.org_settings) || {}).doc_no_fmt || DOC_FMT_DEF); }
function fileFmt(){ return String(((state.data && state.data.org_settings) || {}).file_name_fmt || FILE_FMT_DEF); }
function docPad(){
  const v = parseInt(((state.data && state.data.org_settings) || {}).doc_no_pad, 10);
  return (v >= 1 && v <= 9) ? v : 5;
}
/* ASCII-кусочек: номер уходит и в PDF, и в имя файла на Диске */
function noPart(v, len){
  const s = translit(String(v == null ? '' : v)).replace(/[^A-Za-z0-9.]+/g, '');
  return len ? s.slice(0, len).toUpperCase() : s.toUpperCase();
}
function renderNoFmt(fmt, vals){
  let out = String(fmt).replace(/\{([A-Z]+)\}/g, (m, k) =>
    (vals[k] == null || vals[k] === '') ? '\u0000' : String(vals[k]));
  /* выпавший кусочек уносит с собой соседний разделитель */
  out = out.replace(/\u0000[^A-Za-z0-9\u0000]*/g, '').replace(/[^A-Za-z0-9]*\u0000/g, '');
  return out.replace(/^[^A-Za-z0-9]+|[^A-Za-z0-9]+$/g, '').replace(/([^A-Za-z0-9])\1+/g, '$1');
}
/* Инициалы сотрудника для номера: «Иван Петров» → IP */
function techTag(id){
  const p = (state.data.profiles || []).find(x => x.id === id);
  return p ? noPart(initials(p.display_name), 3) : '';
}
function docNoVals(kind, o){
  const cx = cxById(o.complex_id) || {}, cp = cpById(o.counterparty_id) || {};
  const wt = wtById(o.work_type_id) || {};
  const date = String(o.date || '');
  return {
    TYPE: DOC_TYPE_TAG[kind] || '', DATE: date.replace(/-/g, ''), YEAR: date.slice(0, 4),
    CP: noPart(cp.abbr || cp.name, 4), CX: noPart(cx.abbr || cx.name, 4),
    UNIT: noPart(o.unit_number, 6), TECH: techTag(o.technician_id || o.created_by),
    WT: noPart(enName(wt.name), 6),
    SEQ: o.no == null ? '' : String(o.no).padStart(docPad(), '0')
  };
}
/* Номер документа: работа, пропозал, пикап, продление */
function docNo(kind, o){ return o ? renderNoFmt(docFmt(), docNoVals(kind, o)) : ''; }
function pickNo(pk){
  const j = (state.data.jobs || []).find(x => x.id === pk.job_id) || {};
  return renderNoFmt(docFmt(), { ...docNoVals(pk.ext_of ? 'ext' : 'pick', { ...j, ...pk }),
    SEQ: pk.no == null ? '' : String(pk.no).padStart(docPad(), '0') });
}
function enName(s){
  s = String(s||'');
  if (s.includes('/')){
    const p = s.split('/');
    const en = p[p.length-1].trim();
    if (en) return en;
  }
  return s;
}
function extraItemTextEn(it){
  if (it.kind === 'purchase'){
    const q = Math.max(1, parseInt(it.qty)||1);
    return enName(it.product_name || it.name) + (q > 1 ? ' x' + q : '');
  }
  let sz = '';
  if (it.needs_size){
    const a = Math.max(1, parseInt(it.size_a)||0), b = Math.max(1, parseInt(it.size_b)||0);
    const v = exSizeVal(it);
    sz = ' — ' + ((it.size_a && b > 1) ? a + 'x' + b + ' = ' : '') + v + ' ' + (it.size_unit||'');
  }
  return enName(it.name) + sz;
}
function exSizeVal(it){
  if (!it.needs_size) return 1;
  if (it.size_a || it.size_b){
    return Math.max(1, parseInt(it.size_a)||1) * Math.max(1, parseInt(it.size_b)||1);
  }
  return parseFloat(it.size_value) || 1; // совместимость со старыми записями
}
function extraLineTotal(it){
  if (it.kind === 'purchase') return Math.max(1, parseInt(it.qty)||1) * (parseFloat(it.price)||0);
  const rate = parseFloat(it.price)||0;
  return it.needs_size ? exSizeVal(it) * rate : rate;
}

function extraListHtml(){
  const list = jobDraft.form_data.extra || [];
  if (!list.length) return '';
  return list.map((it, i) => {
    if (it.kind === 'purchase'){
      const prods = [...(state.data.product_types||[])].sort((a,b)=>(a.sort||0)-(b.sort||0));
      return `<div class="ex-item">
        <div class="ex-head"><b>${ic('cart')} ${esc(it.name)}</b>
          <button class="ex-del" onclick="App.exDel(${i})">${ic('close')}</button></div>
        <div class="qty-line">
          <select data-ex-prod="${i}" style="flex:1;min-width:130px">
            <option value="">${t('product')}…</option>
            ${prods.map(p=>`<option value="${p.id}" ${it.product_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}
          </select>
          <input data-ex-qty="${i}" inputmode="numeric" value="${it.qty||1}" style="width:52px;text-align:center" title="${t('qty')}">
          <span class="tiny">×</span>
          <input data-ex-price="${i}" class="price-input" inputmode="decimal" value="${it.price||''}" placeholder="$">
          <span class="money" data-exline="${i}" style="min-width:52px;text-align:right">${extraLineTotal(it)>0?money(extraLineTotal(it)):'—'}</span>
        </div>
      </div>`;
    }
    const lineSum = extraLineTotal(it);
    return `<div class="ex-item">
      <div class="ex-head"><b>${ic('toolbox')} ${esc(it.name)}</b>
        <button class="ex-del" onclick="App.exDel(${i})">${ic('close')}</button></div>
      ${it.needs_size ? `
      <div class="qty-line size-presets">
        ${[1,2,3].map(n=>`<button type="button" class="chip-preset ${(+it.size_a===n && +it.size_b===n)?'on':''}" onclick="App.exPreset(${i},${n})">${n}×${n}</button>`).join('')}
        <span class="tiny">· ${t('custom_size')} ↓</span>
      </div>
      <div class="qty-line">
        ${stepperHtml('exa-'+i, Math.max(1, parseInt(it.size_a)||1))}
        <span class="tiny">×</span>
        ${stepperHtml('exb-'+i, Math.max(1, parseInt(it.size_b)||1))}
        <span class="tiny">= <b data-exsz="${i}">${exSizeVal(it)}</b> ${esc(it.size_unit||'')}</span>
      </div>` : ''}
      <div class="qty-line">
        <span class="tiny">${t('price_lbl')}${it.needs_size ? ' <b>' + t('price_per_size') + '</b>' : ''}:</span>
        <input data-ex-price="${i}" class="price-input" inputmode="decimal" value="${it.price||''}" placeholder="$">
        <span class="money" data-exline="${i}" style="margin-left:auto;min-width:52px;text-align:right">${lineSum>0?money(lineSum):'—'}</span>
      </div>
    </div>`;
  }).join('');
}
function refreshExtraList(){
  const box = document.getElementById('extra-list');
  if (box) box.innerHTML = extraListHtml();
  recalcJob(); autosaveDraft();
}
function extraPickerModal(){
  const list = [...(state.data.extra_works||[])].sort((a,b)=>(a.sort||0)-(b.sort||0));
  openModal(`
    ${modalHead(t('template'), 'plus')}
    ${list.length ? list.map(w => `
      <button class="demo-user" onclick="App.exAdd('${w.id}')">
        <span style="font-size:1.2rem">${w.kind==='purchase'?ic('cart'):ic('toolbox')}</span>
        <span class="grow" style="flex:1;text-align:left">
          <div style="font-weight:900">${esc(w.name)}</div>
          <div class="tiny">${w.kind==='purchase' ? t('kind_purchase') : (w.needs_size ? (szById(w.size_type_id)||{}).name || t('needs_size') : t('kind_work'))}</div>
        </span>
      </button>`).join('')
    : `<div class="tiny">${t('no_templates')}</div>`}
  `);
}
function exAdd(ewId){
  const w = ewById(ewId); if (!w || !jobDraft) return;
  const sz = w.size_type_id ? szById(w.size_type_id) : null;
  const it = {
    id: uid(), ew_id: w.id, name: w.name, kind: w.kind,
    needs_size: !!w.needs_size,
    size_name: sz ? sz.name : '', size_unit: sz ? sz.unit : '',
    size_a: 1, size_b: 1, size_value: 1,
    product_id: null, product_name: '', qty: 1,
    price: +w.price || 0
  };
  jobDraft.form_data.extra = jobDraft.form_data.extra || [];
  jobDraft.form_data.extra.push(it);
  closeModal();
  refreshExtraList();
  dlog('extra: добавлен шаблон', w.name);
}
function exDel(i){
  jobDraft.form_data.extra.splice(i, 1);
  refreshExtraList();
}

